We'll need just three methods in this class, only two of which are public. Let's see the first:
public async Task SendMessage(string message)
{
if (string.IsNullOrWhiteSpace(_conversationId))
{
throw new Exception("No active conversation");
}
Activity userMessage = new Activity
{
From = new ChannelAccount("User"),
Text = message,
Type = ActivityTypes.Message
};
var resourceResponse = await
_client.Conversations.PostActivityAsync(_conversationId, userMessage);
}
